const items = $input.all();
const tableName = $('Gmail Trigger').first().json.subject.toLowerCase()
  .replace(/\s+/g, '_')
  .replace(/[^a-z0-9_]/g, '');

// Extract column names — EXCLUDE SNo
const firstItem = items[0].json;
const columns = Object.keys(firstItem).filter(col => col !== 'SNo');

// Create table SQL — add id UUID column first
const columnDefs = [
  `"id" UUID DEFAULT gen_random_uuid() PRIMARY KEY`,
  ...columns.map(col => `"${col}" TEXT`)
].join(',\n  ');

const createTableSQL = `
CREATE TABLE IF NOT EXISTS ${tableName} (
  ${columnDefs}
);`.trim();

// Create INSERT SQL — SNo excluded, id is auto generated
const insertRows = items
  .filter(item => {
    // Skip empty/null rows
    return columns.some(col => {
      const val = item.json[col];
      return val !== null && val !== undefined && val !== '';
    });
  })
  .map(item => {
    const values = columns.map(col => {
      const val = item.json[col];
      if (val === null || val === undefined || val === '') return 'NULL';
      return `'${String(val).replace(/'/g, "''")}'`;
    }).join(', ');
    return `(${values})`;
  }).join(',\n');

// INSERT only data columns (id auto generated, SNo excluded)
const insertSQL = `
INSERT INTO ${tableName} 
(${columns.map(c => `"${c}"`).join(', ')})
VALUES
${insertRows};`.trim();

const fullSQL = createTableSQL + '\n\n' + insertSQL;

return [{
  json: {
    fullSQL,
    createTableSQL,
    insertSQL,
    tableName,
    totalRows: items.length
  }
}];

const items = $input.all();
const tableName = $('Gmail Trigger')
  .first().json.subject
  .toLowerCase()
  .replace(/\s+/g, '_')
  .replace(/[^a-z0-9_]/g, '');

// Get clean columns from Extract from File — EXCLUDE SNo
const extractedColumns = Object.keys($('Extract from File').first().json)
  .filter(col => col !== 'SNo');

// Build VALUES — SKIP rows where all values are null/empty
const values = items
  .filter(item => {
    return extractedColumns.some(col => {
      const val = item.json[col];
      return val !== null && val !== undefined && val !== '';
    });
  })
  .map(item => {
    const rowValues = extractedColumns.map(col => {
      const val = item.json[col];
      if (val === null || val === undefined || val === '') return 'NULL';
      if (!isNaN(val) && val !== '') return Number(val);
      return `'${String(val).replace(/'/g, "''")}'`;
    });
    return `(${rowValues.join(', ')})`;
  }).join(',\n');

// Final INSERT query
const insertQuery = `
INSERT INTO "${tableName}" 
(${extractedColumns.map(c => `"${c}"`).join(', ')})
VALUES
${values};
`.trim();

return [{
  json: {
    tableName,
    insertQuery,
    totalRows: items.length,
    columns: extractedColumns
  }
}];
